create table if not exists public.dreem_finance_journal_entries(id uuid primary key default gen_random_uuid(),school_id uuid not null,entry_number bigint generated always as identity,entry_type text not null check(entry_type in('charge','payment','allocation','waiver','refund','reversal','deposit','reconciliation','adjustment')),reference_type text not null,reference_id uuid,student_id uuid,debit_account text not null,credit_account text not null,amount numeric(14,2) not null check(amount>0),description text not null,posted_by uuid not null default auth.uid(),posted_at timestamptz not null default now(),reverses_entry_id uuid references public.dreem_finance_journal_entries(id),idempotency_key text not null,unique(school_id,idempotency_key));
create index if not exists dreem_finance_journal_school_posted_idx on public.dreem_finance_journal_entries(school_id,posted_at desc);create index if not exists dreem_finance_journal_student_idx on public.dreem_finance_journal_entries(student_id,posted_at desc);alter table public.dreem_finance_journal_entries enable row level security;revoke all on public.dreem_finance_journal_entries from anon;grant select on public.dreem_finance_journal_entries to authenticated;drop policy if exists "finance roles read journal" on public.dreem_finance_journal_entries;create policy "finance roles read journal" on public.dreem_finance_journal_entries for select to authenticated using(private.dreem_has_role(school_id,array['leadership','bursar','accountant','auditor']));
create table if not exists public.dreem_refund_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null,payment_id uuid not null references public.dreem_financial_payments(id),student_id uuid not null,amount numeric(14,2) not null check(amount>0),reason text not null check(char_length(trim(reason))>=5),status text not null default 'pending_review' check(status in('pending_review','approved','rejected','paid','cancelled')),requested_by uuid not null default auth.uid(),requested_at timestamptz not null default now(),reviewed_by uuid,reviewed_at timestamptz,review_note text,refund_payment_id uuid references public.dreem_financial_payments(id),idempotency_key text not null,unique(school_id,idempotency_key));
create index if not exists dreem_refund_requests_school_status_idx on public.dreem_refund_requests(school_id,status,requested_at desc);alter table public.dreem_refund_requests enable row level security;revoke all on public.dreem_refund_requests from anon;grant select on public.dreem_refund_requests to authenticated;drop policy if exists "finance roles read refunds" on public.dreem_refund_requests;create policy "finance roles read refunds" on public.dreem_refund_requests for select to authenticated using(private.dreem_has_role(school_id,array['leadership','bursar','accountant','auditor']));
create or replace function public.dreem_request_refund(p_payment_id uuid,p_amount numeric,p_reason text,p_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare p public.dreem_financial_payments%rowtype;v_id uuid;v_refunded numeric;begin select * into p from public.dreem_financial_payments where id=p_payment_id;if not found then raise exception 'Payment not found';end if;if not private.dreem_has_role(p.school_id,array['bursar','leadership']) then raise exception 'Not authorized to request refund';end if;select coalesce(sum(amount),0) into v_refunded from public.dreem_refund_requests where payment_id=p_payment_id and status in('approved','paid');if p_amount<=0 or p_amount>p.amount-v_refunded then raise exception 'Refund amount exceeds refundable balance';end if;insert into public.dreem_refund_requests(school_id,payment_id,student_id,amount,reason,idempotency_key)values(p.school_id,p.id,p.student_id,p_amount,trim(p_reason),p_idempotency_key)on conflict(school_id,idempotency_key)do update set idempotency_key=excluded.idempotency_key returning id into v_id;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p.school_id,(select auth.uid()),'finance.refund_requested','refund_request',v_id,jsonb_build_object('payment_id',p.id,'amount',p_amount,'reason',trim(p_reason)));return v_id;end;$$;
revoke all on function public.dreem_request_refund(uuid,numeric,text,text) from public;grant execute on function public.dreem_request_refund(uuid,numeric,text,text) to authenticated;
create or replace function public.dreem_review_refund(p_refund_id uuid,p_decision text,p_note text default '')returns text language plpgsql security definer set search_path='' as $$declare r public.dreem_refund_requests%rowtype;v_status text;begin if p_decision not in('approve','reject')then raise exception 'Invalid decision';end if;select * into r from public.dreem_refund_requests where id=p_refund_id;if not found then raise exception 'Refund request not found';end if;if not private.dreem_has_role(r.school_id,array['accountant','leadership'])then raise exception 'Independent finance review required';end if;if r.requested_by=(select auth.uid())then raise exception 'Requester cannot approve own refund';end if;if r.status<>'pending_review'then raise exception 'Refund request is not pending review';end if;v_status:=case when p_decision='approve'then'approved'else'rejected'end;update public.dreem_refund_requests set status=v_status,reviewed_by=(select auth.uid()),reviewed_at=now(),review_note=trim(p_note)where id=p_refund_id;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(r.school_id,(select auth.uid()),'finance.refund_'||v_status,'refund_request',r.id,jsonb_build_object('amount',r.amount,'note',trim(p_note)));return v_status;end;$$;
revoke all on function public.dreem_review_refund(uuid,text,text) from public;grant execute on function public.dreem_review_refund(uuid,text,text) to authenticated;
create or replace function public.dreem_post_finance_journal(p_school_id uuid,p_entry_type text,p_reference_type text,p_reference_id uuid,p_student_id uuid,p_debit_account text,p_credit_account text,p_amount numeric,p_description text,p_idempotency_key text,p_reverses_entry_id uuid default null)returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;begin if not private.dreem_has_role(p_school_id,array['accountant','leadership'])then raise exception 'Accounting role required';end if;if trim(p_debit_account)=''or trim(p_credit_account)=''or p_debit_account=p_credit_account then raise exception 'Balanced account sides are required';end if;if p_amount<=0 then raise exception 'Amount must be positive';end if;insert into public.dreem_finance_journal_entries(school_id,entry_type,reference_type,reference_id,student_id,debit_account,credit_account,amount,description,idempotency_key,reverses_entry_id)values(p_school_id,p_entry_type,p_reference_type,p_reference_id,p_student_id,trim(p_debit_account),trim(p_credit_account),p_amount,trim(p_description),p_idempotency_key,p_reverses_entry_id)on conflict(school_id,idempotency_key)do update set idempotency_key=excluded.idempotency_key returning id into v_id;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p_school_id,(select auth.uid()),'finance.journal_posted','finance_journal_entry',v_id,jsonb_build_object('entry_type',p_entry_type,'debit',p_debit_account,'credit',p_credit_account,'amount',p_amount));return v_id;end;$$;
revoke all on function public.dreem_post_finance_journal(uuid,text,text,uuid,uuid,text,text,numeric,text,text,uuid) from public;grant execute on function public.dreem_post_finance_journal(uuid,text,text,uuid,uuid,text,text,numeric,text,text,uuid) to authenticated;
create or replace view public.dreem_finance_control_read_model as select s.id as school_id,coalesce((select sum(balance_due)from public.fee_accounts f where f.school_id=s.id),0)as receivables,coalesce((select sum(amount)from public.dreem_financial_payments p where p.school_id=s.id and p.reverses_payment_id is null),0)as gross_collections,coalesce((select sum(amount)from public.dreem_cash_deposit_batches b where b.school_id=s.id and b.status='confirmed'),0)as confirmed_deposits,coalesce((select count(*)from public.dreem_reconciliation_reviews r where r.school_id=s.id and r.status='pending'),0)as pending_reconciliations,coalesce((select count(*)from public.dreem_refund_requests rr where rr.school_id=s.id and rr.status='pending_review'),0)as pending_refunds,coalesce((select count(*)from public.dreem_cash_deposit_batches b where b.school_id=s.id and b.status in('submitted','pending')),0)as pending_deposits from public.schools s;revoke all on public.dreem_finance_control_read_model from anon;grant select on public.dreem_finance_control_read_model to authenticated;